class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int n = colors.size();
        int ans = 0, alt_len = 1;
        for (int i = 1; i < n + k - 1; ++i) {
            if (colors[i % n] != colors[(i - 1) % n]) {
                alt_len++;
            } else {
                alt_len = 1;
            }
            if (alt_len >= k) ans++;
        }
        return ans;
    }
};

